#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-18

# Unit test for src/skills/doctor/scripts/check-peer-skill.py (#4233 deliverable 2).
#
# Builds a fake Claude plugins dir per case and asserts the five verdicts, the
# vendor's fix commands, and the exit codes. No network, no real ~/.claude.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
CHECK="$REPO_ROOT/src/skills/doctor/scripts/check-peer-skill.py"

if [[ ! -f "$CHECK" ]]; then
    echo "FAIL: $CHECK not found" >&2
    exit 1
fi

TMP="$(mktemp -d "${TMPDIR:-/tmp}/ork.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT

PASS=0
FAIL=0

assert_exit() {
    local name="$1" expected="$2" actual="$3"
    if [[ "$expected" -eq "$actual" ]]; then
        echo "  ok  $name (exit=$actual)"
        PASS=$((PASS + 1))
    else
        echo "  FAIL $name (expected exit=$expected, got $actual)"
        FAIL=$((FAIL + 1))
    fi
}

assert_contains() {
    local name="$1" needle="$2" haystack="$3"
    if [[ "$haystack" == *"$needle"* ]]; then
        echo "  ok  $name"
        PASS=$((PASS + 1))
    else
        echo "  FAIL $name (missing: $needle)"
        echo "      output: $haystack"
        FAIL=$((FAIL + 1))
    fi
}

# fixture helpers: write the three files a case needs
write_markets() {
    # $1 dir, $2 install location for typesafe-ai ("" = marketplace absent)
    if [[ -n "$2" ]]; then
        printf '{"typesafe-ai":{"source":{"source":"github","repo":"typesafe-ai/skills"},"installLocation":"%s"},"other":{"installLocation":"/nowhere"}}\n' "$2" > "$1/known_marketplaces.json"
    else
        printf '{"other":{"installLocation":"/nowhere"}}\n' > "$1/known_marketplaces.json"
    fi
}
write_installed() {
    # $1 dir, $2 installed version ("" = plugin absent)
    if [[ -n "$2" ]]; then
        printf '{"version":2,"plugins":{"typesafe@typesafe-ai":[{"scope":"user","version":"%s"}],"x@other":[{"version":"9"}]}}\n' "$2" > "$1/installed_plugins.json"
    else
        printf '{"version":2,"plugins":{"x@other":[{"version":"9"}]}}\n' > "$1/installed_plugins.json"
    fi
}
write_manifest() {
    # $1 clone dir, $2 published version ("" = no version field)
    mkdir -p "$1/.claude-plugin"
    if [[ -n "$2" ]]; then
        printf '{"name":"typesafe-ai","plugins":[{"name":"typesafe","version":"%s","source":"./typesafe"}]}\n' "$2" > "$1/.claude-plugin/marketplace.json"
    else
        printf '{"name":"typesafe-ai","plugins":[{"name":"typesafe","source":"./typesafe"}]}\n' > "$1/.claude-plugin/marketplace.json"
    fi
}

# -----------------------------------------------------------------------------
echo "Test 1: marketplace missing is its own verdict, exit 1, add command in the fix"
D="$TMP/t1"; mkdir -p "$D"
write_markets "$D" ""
write_installed "$D" ""
out="$(python3 "$CHECK" --plugins-dir "$D" 2>&1)" && rc=$? || rc=$?
assert_exit "exit 1" 1 "$rc"
assert_contains "verdict" "MARKETPLACE MISSING" "$out"
assert_contains "fix names the marketplace add" "claude plugin marketplace add typesafe-ai/skills" "$out"
assert_contains "fix names the install" "claude plugin install typesafe@typesafe-ai" "$out"

# -----------------------------------------------------------------------------
echo "Test 2: plugin missing with the marketplace present, exit 1, install command"
D="$TMP/t2"; mkdir -p "$D/clone"
write_markets "$D" "$D/clone"
write_installed "$D" ""
write_manifest "$D/clone" "0.4.0"
out="$(python3 "$CHECK" --plugins-dir "$D" 2>&1)" && rc=$? || rc=$?
assert_exit "exit 1" 1 "$rc"
assert_contains "verdict" "PLUGIN MISSING" "$out"
assert_contains "fix" "Fix: claude plugin install typesafe@typesafe-ai" "$out"
if [[ "$out" == *"MARKETPLACE MISSING"* ]]; then
    echo "  FAIL plugin missing must not read as marketplace missing"; FAIL=$((FAIL + 1))
else
    echo "  ok  distinct from marketplace missing"; PASS=$((PASS + 1))
fi

# -----------------------------------------------------------------------------
echo "Test 3: update available, exit 1, vendor update commands"
D="$TMP/t3"; mkdir -p "$D/clone"
write_markets "$D" "$D/clone"
write_installed "$D" "0.3.0"
write_manifest "$D/clone" "0.4.0"
out="$(python3 "$CHECK" --plugins-dir "$D" 2>&1)" && rc=$? || rc=$?
assert_exit "exit 1" 1 "$rc"
assert_contains "verdict" "UPDATE AVAILABLE (0.3.0 installed, 0.4.0 in marketplace)" "$out"
assert_contains "fix" "claude plugin marketplace update typesafe-ai && claude plugin update typesafe@typesafe-ai" "$out"

# -----------------------------------------------------------------------------
echo "Test 4: up to date, exit 0"
D="$TMP/t4"; mkdir -p "$D/clone"
write_markets "$D" "$D/clone"
write_installed "$D" "0.4.0"
write_manifest "$D/clone" "0.4.0"
out="$(python3 "$CHECK" --plugins-dir "$D" 2>&1)" && rc=$? || rc=$?
assert_exit "exit 0" 0 "$rc"
assert_contains "verdict" "typesafe@typesafe-ai: OK (0.4.0, matches marketplace)" "$out"

# -----------------------------------------------------------------------------
echo "Test 5: version unknown when the clone publishes none, exit 0, --json shape"
D="$TMP/t5"; mkdir -p "$D/clone"
write_markets "$D" "$D/clone"
write_installed "$D" "0.4.0"
write_manifest "$D/clone" ""
out="$(python3 "$CHECK" --plugins-dir "$D" --json 2>&1)" && rc=$? || rc=$?
assert_exit "exit 0" 0 "$rc"
assert_contains "json verdict" '"verdict": "VERSION_UNKNOWN"' "$out"
assert_contains "json installed" '"installed": "0.4.0"' "$out"
assert_contains "json fix null" '"fix": null' "$out"

# -----------------------------------------------------------------------------
echo "Test 6: another plugin ref works, a bad ref is a usage error"
D="$TMP/t6"; mkdir -p "$D"
write_markets "$D" ""
write_installed "$D" ""
out="$(python3 "$CHECK" --plugins-dir "$D" --plugin foo@bar 2>&1)" && rc=$? || rc=$?
assert_exit "exit 1" 1 "$rc"
assert_contains "names the ref" "foo@bar: MARKETPLACE MISSING" "$out"
out="$(python3 "$CHECK" --plugins-dir "$D" --plugin nope 2>&1)" && rc=$? || rc=$?
assert_exit "usage error exit 2" 2 "$rc"

# -----------------------------------------------------------------------------
echo ""
echo "peer-skill check: $PASS passed, $FAIL failed"
[[ "$FAIL" -eq 0 ]]
